# Let's verify the 4-queens solutions
solutions = []

for c0 in range(4):
    for c1 in range(4):
        for c2 in range(4):
            for c3 in range(4):
                cols = [c0, c1, c2, c3]
                # distinct columns
                if len(set(cols)) != 4:
                    continue
                # check diagonals
                valid = True
                for i in range(4):
                    for j in range(i+1, 4):
                        if abs(i-j) == abs(cols[i]-cols[j]):
                            valid = False
                            break
                    if not valid:
                        break
                if valid:
                    solutions.append(cols)

print("Number of solutions:", len(solutions))
for sol in solutions:
    print(sol)
